import{_ as e,o as t,c as n,a0 as i}from"./chunks/framework.B7o6dWmz.js";const m=JSON.parse('{"title":"Capstone: City Tour Kampus Sendiri","description":"","frontmatter":{},"headers":[],"relativePath":"capstone.md","filePath":"capstone.md"}'),r={name:"capstone.md"};function s(o,a,l,d,k,p){return t(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="capstone-city-tour-kampus-sendiri" tabindex="-1">Capstone: City Tour Kampus Sendiri <a class="header-anchor" href="#capstone-city-tour-kampus-sendiri" aria-label="Permalink to &quot;Capstone: City Tour Kampus Sendiri&quot;">​</a></h1><p>Capstone adalah proyek akhir workshop <a href="/workshop.html">Blender: Newbie → Master</a> — <strong>wajib</strong> dan menjadi syarat penuntasan workshop. Kamu merangkai kembali pola dari Level 1, 3, dan 4 menjadi satu karya orisinal: kawasan versimu sendiri, dengan pencahayaan pilihanmu, yang diperkenalkan lewat video city tour MP4 dan model Web 3D interaktif <code>.glb</code>.</p><div class="warning custom-block"><p class="custom-block-title">Prasyarat</p><p>Selesaikan dulu <strong>Level 1–4</strong> (lihat <a href="/workshop.html#peta-jenjang">Peta Jenjang</a>). Capstone memakai paket <code>kg_workshop</code> — instal dulu dari <a href="/unduh.html">Unduh Berkas</a> (panduan instal: <a href="/workshop.html#dua-jalur-kode-monolith-vs-paket-kg-workshop">Dua Jalur Kode</a>).</p></div><p><strong>Estimasi: ±4–6 jam</strong> · artefak dikumpulkan sebagai folder <code>capstone_[NIM]</code>.</p><h2 id="persiapan" tabindex="-1">Persiapan <a class="header-anchor" href="#persiapan" aria-label="Permalink to &quot;Persiapan&quot;">​</a></h2><ol><li>Buka Blender 4.3 dengan file baru, pastikan add-on <strong>KG Workshop</strong> aktif.</li><li>Di N-sidebar → tab <strong>KG Workshop</strong>, klik <strong>Jalankan Capstone</strong> — scene dasar kota contoh terbangun sebagai <em>titik awal</em> yang akan kamu ganti total dengan desainmu.</li><li>Kenali tiga bagian yang akan kamu kerjakan: <code>DENAH_ASCII</code>/masterplan (wilayah), preset pencahayaan, dan rig kamera + timeline.</li></ol><h2 id="langkah-1-—-desain-wilayah" tabindex="-1">Langkah 1 — Desain Wilayah <a class="header-anchor" href="#langkah-1-—-desain-wilayah" aria-label="Permalink to &quot;Langkah 1 — Desain Wilayah&quot;">​</a></h2><p><em>Pola: <a href="/modul/modul-01.html#iii-6-tugas-praktikum">Tugas Praktikum Modul 1</a> + <a href="/modul/modul-03.html#iii-5-task-v-panel-macrolight-m3-mini-proyek-kota">Task V Modul 3</a></em></p><ol><li><p>Sketsakan di kertas kawasan kampus versimu: minimal <strong>1 gedung utama 2 lantai</strong> + <strong>2 bangunan pendukung</strong> + <strong>jalan penghubung</strong> + <strong>1 area terbuka</strong> (taman/plasa).</p></li><li><p>Terjemahkan menjadi masterplan ASCII di konfigurasi paket (<code>config/makro.py</code>) — mengikuti pola <code>PETA_MAKRO_ASCII</code> Modul 3. Untuk interior gedung utama, susun <code>DENAH_ASCII</code> terpisah mengikuti pola Modul 1. Bisa juga lewat konsole Python tanpa mengedit config:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kg_workshop.runner </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> R</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">R.jalankan_capstone(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ascii_makro</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PETA_KAMPUSKU</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># string masterplan buatanmu</span></span></code></pre></div></li><li><p>Jalankan ulang dari panel dan periksa dari <code>Numpad 7</code>: sambungan dinding rapat, proporsi masuk akal, tidak ada objek tumpang tindih.</p></li></ol><p><strong>Kriteria keberhasilan (dari rubrik Modul 1):</strong> denah valid &amp; proporsional, sambungan dinding/T-junction rapat, celah pintu/jendela presisi.</p><h2 id="langkah-2-—-bangun-kawasan-atur-suasana" tabindex="-1">Langkah 2 — Bangun Kawasan &amp; Atur Suasana <a class="header-anchor" href="#langkah-2-—-bangun-kawasan-atur-suasana" aria-label="Permalink to &quot;Langkah 2 — Bangun Kawasan &amp; Atur Suasana&quot;">​</a></h2><p><em>Pola: <a href="/modul/modul-03.html#iii-2-task-ii-simulasi-waktu-siang-sore-malam">Task II–IV Modul 3</a></em></p><ol><li>Tambahkan minimal <strong>2 objek khas kampus</strong> lewat panel MacroLight (pohon, bangku, gapura, halte — pilihan bebas).</li><li>Pilih suasana utama kawasanmu: DAY, SUNSET, atau NIGHT — atau kombinasi via keyframe siklus (lihat Langkah 3). Uji ketiganya dari sudut yang sama sebelum memutuskan.</li><li>Untuk suasana malam: pastikan emission menyala (PJU/jendela) dan World Background ikut gelap.</li></ol><p><strong>Kriteria keberhasilan (dari rubrik Modul 3):</strong> kawasan terbangun utuh, pilihan preset tepat sasaran, mampu menjelaskan pengaruh elevasi matahari terhadap bayangan.</p><h2 id="langkah-3-—-produksi-sinematik" tabindex="-1">Langkah 3 — Produksi Sinematik <a class="header-anchor" href="#langkah-3-—-produksi-sinematik" aria-label="Permalink to &quot;Langkah 3 — Produksi Sinematik&quot;">​</a></h2><p><em>Pola: <a href="/modul/modul-04.html#iii-1-task-i-mengenal-4-kamera-virtual">Task I–V Modul 4</a></em></p><ol><li>Rencanakan tur 10 detik (240 frame @ 24 fps): minimal <strong>2 kamera</strong> — mis. pembuka drone orbit + penutup street eye-level ber-DOF menuju gedung utama.</li><li>Pasang kurva orbit + constraint <code>FOLLOW_PATH</code>/<code>TRACK_TO</code>, atau animasikan keyframe manual (BEZIER untuk gerakan halus, LINEAR untuk gerakan konstan).</li><li>(Opsional) <em>Bake</em> siklus siang→senja→malam sepanjang tur — pola <code>KeyframeAnimator</code> Modul 4.</li><li>Render ke <strong>MP4 H.264, 240 frame</strong> dari kamera utamamu (ganti kamera aktif dulu).</li><li>Ekspor <strong><code>.glb</code></strong> dan buka di web viewer (mis. <a href="https://gltf-viewer.donmccurdy.com/" target="_blank" rel="noreferrer">gltf-viewer</a>) — pastikan objek tampil dan animasi berjalan.</li></ol><p><strong>Kriteria keberhasilan (dari rubrik Modul 4):</strong> kamera &amp; keyframe bekerja, MP4 valid (codec benar, durasi 10 detik), GLB terbuka &amp; beranimasi di web viewer.</p><h2 id="artefak-pengumpulan" tabindex="-1">Artefak &amp; Pengumpulan <a class="header-anchor" href="#artefak-pengumpulan" aria-label="Permalink to &quot;Artefak &amp; Pengumpulan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Artefak</th><th>Format</th><th>Ketentuan</th></tr></thead><tbody><tr><td>Scene capstone</td><td><code>capstone_[NIM].blend</code></td><td>Wilayah + pencahayaan + rig kamera + animasi utuh</td></tr><tr><td>Video city tour</td><td><code>capstone_[NIM].mp4</code></td><td>MP4 H.264, 240 frame @ 24 fps (10 detik), ≥ 2 kamera</td></tr><tr><td>Model Web 3D</td><td><code>capstone_[NIM].glb</code> + PNG viewer</td><td>File ekspor + tangkapan tampilannya di web viewer</td></tr><tr><td>Masterplan &amp; denah</td><td><code>.py</code> atau PNG</td><td>Teks ASCII wilayah versimu (tersimpan di konfigurasi) + tangkapan <code>Numpad 7</code></td></tr><tr><td>Laporan singkat</td><td>PDF/MD</td><td>Alur desain: ASCII → keputusan pencahayaan (tabel preset) → tabel keyframe kamera</td></tr></tbody></table><p>Kumpulkan sebagai satu folder <code>capstone_[NIM]</code> — diverifikasi dosen pengampu bersama portofolio <code>prak1–prak4</code> saat praktikum dimulai.</p><h2 id="rubrik-penilaian" tabindex="-1">Rubrik Penilaian <a class="header-anchor" href="#rubrik-penilaian" aria-label="Permalink to &quot;Rubrik Penilaian&quot;">​</a></h2><p>Rubrik gabungan dari Modul 1, 3, dan 4 (kriteria tidak diubah) + kolom orisinalitas:</p><table tabindex="0"><thead><tr><th>Kriteria</th><th>Bobot</th><th>Acuan</th></tr></thead><tbody><tr><td>Desain wilayah ASCII → kawasan 3D (denah valid, sambungan rapat, proporsional)</td><td>25%</td><td>Rubrik M1 — Konversi Denah</td></tr><tr><td>Kawasan &amp; pencahayaan (objek khas, preset tepat, analisis bayangan)</td><td>25%</td><td>Rubrik M3 — Task II–V</td></tr><tr><td>Produksi sinematik (kamera &amp; keyframe bekerja, MP4 valid 10 detik, GLB beranimasi)</td><td>30%</td><td>Rubrik M4 — Task I–V</td></tr><tr><td>Orisinalitas &amp; kelengkapan laporan (karya sendiri, bukan scene contoh; laporan runtut)</td><td>20%</td><td>Khusus capstone</td></tr></tbody></table><p>Kategori nilai mengikuti skala rubrik Modul 1: <strong>A ≥ 80 · B 70–79.99 · C 60–69.99 · D/E &lt; 60</strong>.</p><h2 id="kembali-ke-workshop" tabindex="-1">Kembali ke Workshop <a class="header-anchor" href="#kembali-ke-workshop" aria-label="Permalink to &quot;Kembali ke Workshop&quot;">​</a></h2><p>Selesai capstone = workshop tuntas. Kembali ke <a href="/workshop.html">Workshop Blender: Newbie → Master</a> untuk menutup ceklis akhir portofoliomu.</p>`,27)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
